CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(120) NOT NULL,public_slug varchar(80) UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE areas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name varchar(120) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX areas_tenant_name_idx ON areas(tenant_id,lower(name));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),area_id uuid REFERENCES areas(id),email varchar(254) NOT NULL,name varchar(120) NOT NULL,password_hash text NOT NULL,role varchar(20) NOT NULL CHECK(role IN('admin','platform_admin','company_admin','agent')),avatar_data bytea,avatar_content_type varchar(40),active boolean NOT NULL DEFAULT true,deleted_at timestamptz,UNIQUE(tenant_id,email));
CREATE TABLE tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),area_id uuid NOT NULL REFERENCES areas(id),protocol integer NOT NULL,requester_name varchar(120) NOT NULL,department varchar(120) NOT NULL,contact varchar(254),title varchar(180) NOT NULL,summary text NOT NULL,product varchar(80) NOT NULL,priority varchar(20) NOT NULL DEFAULT 'normal',status varchar(30) NOT NULL DEFAULT 'new',public_token_hash varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,protocol));
CREATE TABLE resolutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ticket_id uuid UNIQUE NOT NULL REFERENCES tickets(id),confirmed_problem text NOT NULL,root_cause text NOT NULL,solution text NOT NULL,validation text NOT NULL,reusable boolean NOT NULL DEFAULT false,sanitized_document jsonb);
CREATE TABLE ai_configs(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),provider varchar(30) NOT NULL DEFAULT 'ollama',model varchar(120) NOT NULL,embedding_model varchar(120) NOT NULL,conversation_source varchar(20) NOT NULL DEFAULT 'ollama',embedding_source varchar(20) NOT NULL DEFAULT 'ollama',api_base_url varchar(500),api_key_encrypted bytea,context_size integer NOT NULL DEFAULT 8192,max_tokens integer NOT NULL DEFAULT 512,temperature varchar(8) NOT NULL DEFAULT '0.2',response_timeout_seconds integer NOT NULL DEFAULT 90,valid_response_rules jsonb NOT NULL DEFAULT '{"allow_plain_text_repair":true,"reject_repeated_questions":true,"require_context_reference":false,"require_summary_fields":true}'::jsonb,runtime_profiles jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE skills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name varchar(160) NOT NULL,source_url varchar(1000) NOT NULL,content text NOT NULL,sha256 varchar(64) NOT NULL,scope varchar(20) NOT NULL DEFAULT 'all',active boolean NOT NULL DEFAULT false,created_by uuid NOT NULL REFERENCES users(id),last_test_model varchar(120),last_test_success boolean,last_test_ms integer,last_test_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,sha256));
CREATE TABLE knowledge_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),area_id uuid NOT NULL REFERENCES areas(id),title varchar(180) NOT NULL,filename varchar(255) NOT NULL,content_type varchar(100) NOT NULL,sha256 varchar(64) NOT NULL,status varchar(20) NOT NULL DEFAULT 'active',uploaded_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,area_id,sha256));
CREATE TABLE knowledge_chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),document_id uuid NOT NULL REFERENCES knowledge_documents(id) ON DELETE CASCADE,chunk_index integer NOT NULL,content text NOT NULL,UNIQUE(document_id,chunk_index));
CREATE TABLE ticket_status_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,status varchar(30) NOT NULL,changed_by uuid REFERENCES users(id),entered_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE usage_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),event_type varchar(40) NOT NULL,model varchar(120),success boolean NOT NULL DEFAULT true,duration_ms integer,prompt_tokens integer,response_tokens integer,tokens_estimated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,filename varchar(255) NOT NULL,content_type varchar(40) NOT NULL,size_bytes integer NOT NULL,data bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),actor_user_id uuid REFERENCES users(id),actor_role varchar(20) NOT NULL,action varchar(80) NOT NULL,target_type varchar(40) NOT NULL,target_id varchar(80),details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX users_tenant_area_idx ON users(tenant_id,area_id);CREATE INDEX tickets_tenant_status_idx ON tickets(tenant_id,status,created_at DESC);CREATE INDEX tickets_tenant_area_idx ON tickets(tenant_id,area_id,created_at DESC);CREATE INDEX resolutions_tenant_idx ON resolutions(tenant_id);CREATE INDEX knowledge_documents_tenant_idx ON knowledge_documents(tenant_id,area_id,created_at DESC);CREATE INDEX knowledge_chunks_tenant_idx ON knowledge_chunks(tenant_id,document_id);CREATE INDEX ticket_status_history_tenant_idx ON ticket_status_history(tenant_id,ticket_id,entered_at);CREATE INDEX usage_events_tenant_idx ON usage_events(tenant_id,created_at DESC);CREATE INDEX skills_tenant_idx ON skills(tenant_id,created_at DESC);CREATE INDEX ticket_attachments_tenant_idx ON ticket_attachments(tenant_id,ticket_id);CREATE INDEX audit_logs_tenant_idx ON audit_logs(tenant_id,created_at DESC);
ALTER TABLE users ENABLE ROW LEVEL SECURITY;ALTER TABLE users FORCE ROW LEVEL SECURITY;ALTER TABLE areas ENABLE ROW LEVEL SECURITY;ALTER TABLE areas FORCE ROW LEVEL SECURITY;ALTER TABLE tickets ENABLE ROW LEVEL SECURITY;ALTER TABLE tickets FORCE ROW LEVEL SECURITY;ALTER TABLE resolutions ENABLE ROW LEVEL SECURITY;ALTER TABLE resolutions FORCE ROW LEVEL SECURITY;ALTER TABLE ai_configs ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_configs FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_documents ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_documents FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_chunks ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_chunks FORCE ROW LEVEL SECURITY;ALTER TABLE ticket_status_history ENABLE ROW LEVEL SECURITY;ALTER TABLE ticket_status_history FORCE ROW LEVEL SECURITY;ALTER TABLE usage_events ENABLE ROW LEVEL SECURITY;ALTER TABLE usage_events FORCE ROW LEVEL SECURITY;ALTER TABLE skills ENABLE ROW LEVEL SECURITY;ALTER TABLE skills FORCE ROW LEVEL SECURITY;ALTER TABLE ticket_attachments ENABLE ROW LEVEL SECURITY;ALTER TABLE ticket_attachments FORCE ROW LEVEL SECURITY;ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;ALTER TABLE audit_logs FORCE ROW LEVEL SECURITY;
CREATE POLICY users_tenant ON users USING(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY areas_tenant ON areas USING(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid);
