CREATE POLICY knowledge_documents_tenant ON knowledge_documents USING(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY knowledge_chunks_tenant ON knowledge_chunks USING(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY ticket_status_history_tenant ON ticket_status_history USING(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY usage_events_tenant ON usage_events USING(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY skills_tenant ON skills USING(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY ticket_attachments_tenant ON ticket_attachments USING(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid);
CREATE POLICY audit_logs_tenant ON audit_logs USING(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(current_setting('app.platform_admin',true)='true' OR tenant_id=current_setting('app.tenant_id',true)::uuid);
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
